"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["80200"],{78157(a){a.exports=JSON.parse('{"id":"F447","slug":"balance-of-payments-identity","name":"Balance of Payments Identity","subject":"International Finance","section":"Global Finance","topic":"Balance of payments and capital flows","level":"Intermediate","aliases":["balance of payments and capital flows","current account","financial account","saving investment gap"],"formula":{"latex":"CA=TB+PI+SI,\\\\quad CA+KA+FA+EO=0,\\\\quad CA=S-I","also":[],"text":"Current account = trade balance + primary income (investment income, wages) + secondary income (transfers and remittances); Current account + capital account + financial account + errors = 0, where the financial account is net inflows (+) of capital; Current account = national saving - domestic investment"},"symbols":[{"symbol":"TB","meaning":"Trade balance: exports minus imports of goods and services","unit":"money"},{"symbol":"PI, SI","meaning":"Net primary income and net secondary income (transfers)","unit":"money"},{"symbol":"KA","meaning":"Capital account: small capital transfers","unit":"money"},{"symbol":"FA","meaning":"Financial account: net capital inflows (investment and borrowing from abroad), sign shown as inflow positive","unit":"money"},{"symbol":"EO","meaning":"Errors and omissions","unit":"money"}],"when_to_use":"Use it to see how a country pays for its overseas spending. A current account deficit means the country spends more than it earns abroad and must attract capital inflows of the same size, from borrowing or from foreign investors buying assets. The saving-investment version gives the same message: a deficit means domestic investment exceeds national saving. Persistent deficits are not harmful by themselves, but depend on investor confidence.","worked_example":{"problem":"A country has a trade deficit of 420, net primary income of +90, net transfers of +30, a capital account of +2 and errors of -5. GDP is 10,000. National saving is 18% of GDP and investment 21%.","inputs":{"tb":-420,"pi":90,"si":30,"ka":2,"eo":-5,"gdp":10000,"sav":18,"inv":21},"steps":[{"label":"Current account = TB + PI + SI","working":"-420+90+30","value":"-300.00"},{"label":"Current account as a share of GDP","working":"-300 / 10000","value":"-3.0%"},{"label":"Net capital inflow needed = -(CA + KA + EO)","working":"-(-300+2+-5)","value":"303.00"},{"label":"Current account from saving minus investment","working":"(0.18-0.21) x 10000","value":"-300.00"},{"label":"Saving-investment gap as a share of GDP","working":"0.18-0.21","value":"-3.0%"}],"answer":"The current account is -300.00, or -3.0% of GDP. To balance, the financial account must show net capital inflows of 303.00. The saving-investment gap gives a current account of -300.00, which is -3.0% of GDP and should be close to the first figure if the data are consistent."},"calculator":{"available":true,"inputs":[{"id":"tb","label":"Trade balance","unit":"money","type":"number","default":-420,"hint":""},{"id":"pi","label":"Net primary income","unit":"money","type":"number","default":90,"hint":""},{"id":"si","label":"Net secondary income","unit":"money","type":"number","default":30,"hint":""},{"id":"ka","label":"Capital account","unit":"money","type":"number","default":2,"hint":""},{"id":"eo","label":"Errors and omissions","unit":"money","type":"number","default":-5,"hint":""},{"id":"gdp","label":"GDP","unit":"money","type":"number","default":10000,"hint":""},{"id":"sav","label":"National saving (share of GDP)","unit":"%","type":"number","default":18,"hint":""},{"id":"inv","label":"Investment (share of GDP)","unit":"%","type":"number","default":21,"hint":""}],"checks":[{"expr":"gdp>0","message":"GDP must be above zero."}],"steps":[{"id":"ca","label":"Current account = TB + PI + SI","expr":"tb+pi+si","format":"money"},{"id":"cagdp","label":"Current account as a share of GDP","expr":"ca/gdp","format":"pct1"},{"id":"fa","label":"Net capital inflow needed = -(CA + KA + EO)","expr":"-(ca+ka+eo)","format":"money"},{"id":"gap","label":"Current account from saving minus investment","expr":"(sav-inv)*gdp","format":"money"},{"id":"cagdp2","label":"Saving-investment gap as a share of GDP","expr":"sav-inv","format":"pct1"}],"results":["ca","cagdp","fa","cagdp2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ca":-300,"cagdp":-0.03,"fa":303,"gap":-300,"cagdp2":-0.03}},"finder":{"finds":"How a current account gap is financed","needs":"Trade balance, income, transfers, capital account, GDP, saving and investment"},"related":[{"slug":"gdp-nominal-real","name":"GDP: Expenditure Approach, Real GDP and Deflator"},{"slug":"comparative-advantage","name":"Comparative Advantage and Gains from Trade"},{"slug":"reserve-adequacy","name":"Reserve Adequacy Metrics"}],"related_ids":["F080","F095","F439"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mi>A</mi><mo>=</mo><mi>T</mi><mi>B</mi><mo>+</mo><mi>P</mi><mi>I</mi><mo>+</mo><mi>S</mi><mi>I</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>C</mi><mi>A</mi><mo>+</mo><mi>K</mi><mi>A</mi><mo>+</mo><mi>F</mi><mi>A</mi><mo>+</mo><mi>E</mi><mi>O</mi><mo>=</mo><mn>0</mn><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>C</mi><mi>A</mi><mo>=</mo><mi>S</mi><mo>\u2212</mo><mi>I</mi></mrow><annotation encoding=\\"application/x-tex\\">CA=TB+PI+SI,\\\\quad CA+KA+FA+EO=0,\\\\quad CA=S-I</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>C</mi><mi>A</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle CA</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>T</mi><mi>B</mi><mo>+</mo><mi>P</mi><mi>I</mi><mo>+</mo><mi>S</mi><mi>I</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =TB+PI+SI</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>C</mi><mi>A</mi><mo>+</mo><mi>K</mi><mi>A</mi><mo>+</mo><mi>F</mi><mi>A</mi><mo>+</mo><mi>E</mi><mi>O</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle CA+KA+FA+EO</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mn>0</mn></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =0</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>C</mi><mi>A</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle CA</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>S</mi><mo>\u2212</mo><mi>I</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =S-I</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"backtest-performance-summary","name":"Backtest Summary: Return, Risk, Drawdown and Information Ratio"},"next":{"slug":"bank-balance-sheet-ratios","name":"Bank Balance Sheet Ratios"},"lesson":null,"total":522}')}}]);